class Api {
  static String base = const String.fromEnvironment('API_URL', defaultValue: 'http://10.0.2.2:4100');
  static String token = '';
  static Future<dynamic> request(String method,String path,[Map<String,dynamic>? data]) async {
    final uri=Uri.parse('$base/api$path');
    final headers={'Content-Type':'application/json',if(token.isNotEmpty)'Authorization':'Bearer $token'};
    final request = http.Request(method, uri);
    request.headers.addAll(headers);
    if (data != null) request.body = jsonEncode(data);
    final res = await http.Response.fromStream(
      await request.send().timeout(const Duration(seconds: 18)),
    );
    dynamic body;
    try { body=jsonDecode(utf8.decode(res.bodyBytes)); } catch (_) {throw Exception('پاسخ سرور نامعتبر است');}
    if(res.statusCode>=400)throw Exception(body is Map ? (body['error']??'خطای سرور').toString() : 'خطای سرور ${res.statusCode}');
    return body;
  }
}
